Boolean dei_rf1_rx_hhu_add(void)
{
	UInt32 hhu_sn ; 
    UInt8  i ;

    hhu_sn = ((dei_rf1_vars.rx_data >> 8)&0x00FFFFFF);

    if( hhu_sn == 0x000000000 ) return FALSE ; 
        
    dei_rf1_vars.hhu_sn_used = hhu_sn ;

	if( dei_rf1_rx_hhu_check() == FALSE )
	{
		dei_rf1_hhu.idx ++ ; 
		dei_rf1_hhu.idx = dei_rf1_hhu.idx % DEI_RF1_HHU_MAX ;
		
		dei_rf1_vars.hhu_sn_used = hhu_sn ; 

		dei_rf1_hhu.id[dei_rf1_hhu.idx]=hhu_sn ;
		
		return TRUE ;  
	}

	return FALSE ; 
}

